function buildSubject(pattern: string, values: Readonly<Record<string, string>>): string {
  let result = pattern
  for (const [name, value] of Object.entries(values)) {
    validateSubjectToken(name, value)
    result = result.split(`{${name}}`).join(value)
  }
  return result
}

function validateSubjectToken(name: string, value: string): void {
  if (value.length === 0 || /[.*>\s]/u.test(value)) {
    throw new TypeError(`subject parameter ${name} is empty or contains a separator, wildcard, or whitespace`)
  }
}

